// Local isolated file parser. Original pinned SheetJS CE 0.20.2; no network other than same-site vendor, no formula evaluation.
importScripts('./sheetjs-0.20.2.js');
self.onmessage=e=>{try{const {format,sample}=e.data;if(!['xlsx','xls','csv'].includes(format))throw Error();let input=e.data.bytes;if(sample){const sheet=XLSX.utils.aoa_to_sheet([['题目','答案','A','B'],['本机文件导入虚构题一','A','A. 虚构甲','B. 虚构乙'],['本机文件导入虚构题二','B','A. 虚构甲','B. 虚构乙']]),book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,sheet,'本机虚构导入');input=XLSX.write(book,{type:'array',bookType:format==='xls'?'biff8':format});}if(!(input instanceof ArrayBuffer)||input.byteLength>2097152)throw Error();let wb;if(format==='csv')wb=XLSX.read(new TextDecoder('utf-8',{fatal:true}).decode(input).replace(/^\uFEFF/,''),{type:'string',raw:true,cellFormula:true});else wb=XLSX.read(input,{type:'array',cellFormula:true,cellHTML:false,bookVBA:true});if(wb.vbaraw||!Array.isArray(wb.SheetNames)||!wb.SheetNames.length)throw Error();const name=wb.SheetNames[0],sheet=wb.Sheets[name],range=XLSX.utils.decode_range(sheet['!ref']||'A1:A1');if(range.s.r!==0||range.s.c!==0||range.e.r<1||range.e.r>1001||range.e.c<2||range.e.c>63)throw Error();for(const[key,c]of Object.entries(sheet)){if(key[0]==='!')continue;if(c.f||c.F||c.l||c.t==='e')throw Error();}const raw=XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:true,blankrows:true}),cols=range.e.c+1,value=v=>{if(!['string','number','boolean'].includes(typeof v)||typeof v==='number'&&!Number.isFinite(v))throw Error();const s=String(v);if(s.length>5000)throw Error();return s;},row=r=>Array.from({length:cols},(_,i)=>value(r?.[i]??'')),headers=row(raw[0]).map(x=>x.trim()),rows=raw.slice(1).map((r,i)=>({sourceRow:i+2,cells:row(r)})).filter(r=>r.cells.some(c=>c.trim()));if(rows.length<1||rows.length>1000)throw Error();self.postMessage({ok:true,grid:{format,headers,rows,sheetName:name,sheetCount:wb.SheetNames.length}});}catch{self.postMessage({ok:false,code:'LOCAL_FILE_PARSE_REJECTED'});}};
